import { useRoute } from 'vue-router'; //this.$route
import { onBeforeMount, reactive } from 'vue';
import { getSongSheet, getSongSheetDetails } from '@/request/API/SongSheet';
import TheTop from '@/components/SongSheet/TheTop.vue'; //引入组件不加括号

export default {
  __name: 'SongSheet',
  setup(__props, {
    expose
  }) {
    expose();
    const state = reactive({
      creator: {},
      playlist: {},
      singleSheetDetials: {}
    });
    onBeforeMount(async () => {
      let id = useRoute().query.id;
      let res = await getSongSheet(id);
      let res1 = await getSongSheetDetails(id);
      console.log(res1.data);
      state.singleSheetDetials = res1.data;
      state.playlist = res.data.playlist;
      state.creator = res.data.playlist.creator;
      console.log(state.playlist);
      //  console.log(state.playlist)
      sessionStorage.setItem('itemDetial', JSON.stringify(state)); //在页面渲染时未拿到数据
    });

    const __returned__ = {
      state,
      get useRoute() {
        return useRoute;
      },
      onBeforeMount,
      reactive,
      get getSongSheet() {
        return getSongSheet;
      },
      get getSongSheetDetails() {
        return getSongSheetDetails;
      },
      TheTop
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
